static string E(const string&s){static constexpr char H[]="0123456789ABCDEF";string r;for(auto x:s){auto c=(unsigned char)x;if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.'||c=='~')r+=char(c);else{r+='%';r+=H[c>>4];r+=H[c&15];}}return r;}static string V(yyjson_val*v){size_t n=0;char*p=yyjson_val_write(v,0,&n);if(!p)return {};string r(p,n);free(p);return r;}static string G(yyjson_val*o,const char*k){auto v=o?yyjson_obj_get(o,k):nullptr;return v&&yyjson_is_str(v)?string(yyjson_get_str(v),yyjson_get_len(v)):string();}
