static unique_ptr<GlobalTableFunctionState>I(ClientContext&,TableFunctionInitInput&i){auto s=make_uniq<State>();auto&b=i.bind_data->Cast<Bind>();s->cols=i.column_ids;s->start=ResolveTimeSpec("start_time",b.start);s->end=ResolveTimeSpec("end_time",b.end);int64_t a,z;if(!ParseRfc3339ToNanos(s->start.c_str(),a)||!ParseRfc3339ToNanos(s->end.c_str(),z)||a>=z)throw InvalidInputException("read_gcloud_metrics: start_time must be before end_time");return s;}static void Scan(ClientContext&c,TableFunctionInput&i,DataChunk&o){auto&b=i.bind_data->Cast<Bind>();auto&s=i.global_state->Cast<State>();while(s.points.empty()&&!s.done)Fetch(c,b,s);idx_t n=0;while(n<STANDARD_VECTOR_SIZE&&!s.points.empty()&&(b.max==0||s.emitted<idx_t(b.max))){Map(b,s,s.points.front(),o,n++);s.points.pop_front();s.emitted++;}if(b.max>0&&s.emitted>=idx_t(b.max)){s.points.clear();s.done=true;}o.SetCardinality(n);}
